def unique_digits(x):
    """Given a list of positive integers x. return a sorted list of all 
    elements that hasn't any even digit.

    Note: Returned list should be sorted in increasing order.

    For example:
    >>> unique_digits([15, 33, 1422, 1])
    [1, 15, 33]
    >>> unique_digits([152, 323, 1422, 10])
    []
    """
    result = []
    for num in x:
        has_even = False
        for digit in str(num):
            if int(digit) % 2 == 0:
                has_even = True
                break
        if not has_even:
            result.append(num)
    return sorted(result)

def move_one_ball(arr):
    """Return True if we can obtain a non-decreasing sorted array by performing any number of right shifts on arr."""
    n = len(arr)
    if n <= 1:
        return True

    # Generate all possible arrays after k right shifts (k from 0 to n-1)
    for k in range(n):
        shifted = arr[-k:] + arr[:-k] if k != 0 else arr[:]  # For k=0, this gives original; but we can handle separately
        # Actually simpler: right shift by k means last k elements move to front.
        # Let's compute correctly:
        # Right shift once: [a1,a2,...,an] -> [an, a1, a2, ..., a_{n-1}]
        # So after k shifts: arr[-k:] + arr[:-k]
        if k == 0:
            candidate = arr[:]
        else:
            candidate = arr[-k:] + arr[:-k]

        # Check if candidate is sorted in non-decreasing order
        if all(candidate[i] <= candidate[i+1] for i in range(len(candidate)-1)):
            return True

    return False
